package net.minecraft.client.gui.screens;import net.minecraft.network.chat.Component;import net.minecraft.client.gui.Font;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.events.GuiEventListener;import net.minecraft.client.gui.components.Renderable;import net.minecraft.client.gui.narration.NarratableEntry;public class Screen{protected Component title;public int width,height;protected Font font;public java.util.List<net.minecraft.client.gui.components.Button> widgets=new java.util.ArrayList<>();protected Screen(Component c){title=c;}protected void init(){}public void init(net.minecraft.client.Minecraft m,int w,int h){width=w;height=h;font=new Font();widgets.clear();init();}protected <T extends GuiEventListener & Renderable & NarratableEntry>T addRenderableWidget(T w){widgets.add((net.minecraft.client.gui.components.Button)w);return w;}public void tick(){}public void render(GuiGraphics g,int x,int y,float p){}public boolean isPauseScreen(){return false;}public boolean shouldCloseOnEsc(){return false;}}
